import os
import requests

class AzureSpeechClient:
    def __init__(self, region: str = None, api_key: str = None):
        self.region = region or os.environ.get("AZURE_SPEECH_REGION")
        self.api_key = api_key or os.environ.get("AZURE_SPEECH_KEY")
        if not self.region or not self.api_key:
            raise ValueError("Azure Speech region and API key must be provided or set in environment variables.")
        self.base_url = f"https://{self.region}.api.cognitive.microsoft.com/speechtotext/v3.1"

    def _get_headers(self):
        return {"Ocp-Apim-Subscription-Key": self.api_key}

    def submit_transcription(self, display_name: str, locale: str, content_urls: list, properties: dict = None):
        url = f"{self.base_url}/transcriptions"
        json_payload = {
            "displayName": display_name,
            "locale": locale,
            "contentUrls": content_urls,
            "properties": properties or {}
        }
        response = requests.post(url, headers=self._get_headers(), json=json_payload)
        response.raise_for_status()
        return response.json()

    def get_transcription(self, transcription_id: str):
        url = f"{self.base_url}/transcriptions/{transcription_id}"
        response = requests.get(url, headers=self._get_headers())
        response.raise_for_status()
        return response.json()

    def get_transcription_files(self, transcription_id: str):
        url = f"{self.base_url}/transcriptions/{transcription_id}/files"
        response = requests.get(url, headers=self._get_headers())
        response.raise_for_status()
        return response.json()

from dataclasses import dataclass, field
from typing import List, Optional

@dataclass
class TranscriptionProperties:
    wordLevelTimestampsEnabled: Optional[bool] = False
    diarizationEnabled: Optional[bool] = False
    languageIdentification: Optional[dict] = None
    # Add other properties as needed

@dataclass
class TranscriptionRequest:
    displayName: str
    locale: str
    contentUrls: List[str]
    properties: TranscriptionProperties = field(default_factory=TranscriptionProperties)

@dataclass
class TranscriptionResult:
    id: str
    status: str
    locale: str
    createdDateTime: str
    lastActionDateTime: str
    displayName: str
    links: dict = field(default_factory=dict)
    properties: dict = field(default_factory=dict)

@dataclass
class TranscriptionFile:
    kind: str
    properties: dict
    self: str

@dataclass
class WordLevelTimestamp:
    word: str
    offset: int # in ticks (100-nanosecond units)
    duration: int # in ticks (100-nanosecond units)

@dataclass
class DiarizationSpeaker:
    speaker: int
    offset: int
    duration: int
    text: str

# Helper to convert Azure's ticks to seconds
def ticks_to_seconds(ticks: int) -> float:
    return ticks / 10000000.0

import requests
from speech_client import AzureSpeechClient
from speech_models import TranscriptionRequest, TranscriptionProperties, WordLevelTimestamp, ticks_to_seconds

def request_timestamped_transcript(audio_uri: str, language_code: str, job_name: str, client: AzureSpeechClient):
    properties = TranscriptionProperties(wordLevelTimestampsEnabled=True)
    request = TranscriptionRequest(
        displayName=job_name,
        locale=language_code,
        contentUrls=[audio_uri],
        properties=properties
    )

    response_json = client.submit_transcription(
        display_name=request.displayName,
        locale=request.locale,
        content_urls=request.contentUrls,
        properties=request.properties.__dict__ # Convert dataclass to dict for API call
    )
    return {'job_id': response_json['self'].split('/')[-1], 'status': 'SUBMITTED'}

def extract_word_timestamps(transcription_result: dict) -> list[WordLevelTimestamp]:
    timestamps = []
    for recognized_phrase in transcription_result.get('recognizedPhrases', []):
        for word_info in recognized_phrase.get('nBest', [{}])[0].get('words', []):
            timestamps.append(WordLevelTimestamp(
                word=word_info['word'],
                offset=word_info['offset'],
                duration=word_info['duration']
            ))
    return timestamps

def extract_segment_timestamps(transcription_result: dict) -> list[dict]:
    segments = []
    for recognized_phrase in transcription_result.get('recognizedPhrases', []):
        text = recognized_phrase.get('nBest', [{}])[0].get('display', '')
        offset_ticks = recognized_phrase.get('offset', 0)
        duration_ticks = recognized_phrase.get('duration', 0)

        segments.append({
            'text': text,
            'offset_seconds': ticks_to_seconds(offset_ticks),
            'duration_seconds': ticks_to_seconds(duration_ticks)
        })
    return segments
